import { z } from 'zod';
import type { ProfileRuntime } from '../../types/design-profile';

const message = z.object({
  message: z.object({ content: z.array(z.unknown()) }),
});
const readCall = z.object({
  type: z.literal('tool_use'),
  id: z.string(),
  name: z.literal('Read'),
  input: z.object({ file_path: z.string().min(1) }),
});
const toolResult = z.object({
  type: z.literal('tool_result'),
  tool_use_id: z.string(),
  is_error: z.boolean().optional(),
  content: z.unknown(),
});
const image = z.object({ type: z.literal('image') });
const cursorRead = z.object({
  type: z.literal('tool_call'),
  subtype: z.literal('completed'),
  tool_call: z.object({
    readToolCall: z.object({
      args: z.object({ path: z.string().min(1) }),
      result: z.object({
        success: z.object({ dataBlobId: z.string().min(1) }),
      }),
    }),
  }),
});

export const readNativeImagePaths = (
  runtime: ProfileRuntime,
  events: Array<Record<string, unknown>>,
): string[] => {
  const paths = new Set<string>();
  const reads = new Map<string, string>();
  for (const event of events) {
    if (runtime === 'cursor') {
      const read = cursorRead.safeParse(event);
      if (read.success) paths.add(read.data.tool_call.readToolCall.args.path);
    }
    if (runtime !== 'claude') continue;
    const parsed = message.safeParse(event);
    if (!parsed.success) continue;
    if (event.type === 'assistant') {
      for (const block of parsed.data.message.content) {
        const call = readCall.safeParse(block);
        if (call.success) reads.set(call.data.id, call.data.input.file_path);
      }
    }
    if (event.type !== 'user') continue;
    const results = parsed.data.message.content.flatMap((block) => {
      const result = toolResult.safeParse(block);
      return result.success ? [result.data] : [];
    });
    for (const result of results) {
      const file = reads.get(result.tool_use_id);
      const hasImage =
        Array.isArray(result.content) &&
        result.content.some((block) => image.safeParse(block).success);
      const isImageResult =
        results.length === 1 && image.safeParse(event.tool_use_result).success;
      if (file && !result.is_error && (hasImage || isImageResult))
        paths.add(file);
    }
  }
  return [...paths];
};
